//! The MCP tool reference, generated from the registry.
//!
//! `neurolithe tools` prints it; `docs/src/mcp/tools.md` is its committed
//! output, and a test fails when that file is stale.

use serde_json::Value;
use std::fmt::Write;

use super::registry::{Group, INSPECT_VIEWS, TOOLS, ToolDef};

/// Path of the committed reference, relative to the repository root.
pub const REFERENCE_PATH: &str = "docs/src/mcp/tools.md";

/// The full Markdown reference page.
pub fn markdown() -> String {
    let mut out = String::new();
    out.push_str(
        "<!-- Generated by `neurolithe tools --markdown` from the tool registry \
         (src/interfaces/mcp/registry.rs). Do not edit by hand. -->\n\n",
    );
    out.push_str("# Tool reference\n\n");
    out.push_str(
        "Every tool works on the **active workspace**. Tool failures come back as a \
         result with `isError: true` and a message naming the problem; an unknown tool \
         is a JSON-RPC error (`-32602`). JSON results are sent as text and, to clients \
         on protocol 2025-06-18 or later, also as `structuredContent` (a top-level \
         array is wrapped as `{\"items\": [...]}`).\n\n",
    );
    out.push_str("| Tool | Summary | Hints |\n|---|---|---|\n");
    for tool in TOOLS {
        let _ = writeln!(
            out,
            "| [`{}`](#{}) | {} | {} |",
            tool.name,
            tool.name,
            tool.title,
            hints(tool)
        );
    }
    out.push_str(
        "\nTools marked *pinned: hidden* are not listed when the server runs with \
         `[mcp] allow_workspace_switch = false`: such a server stays on its startup \
         workspace and can't reach any other one. Calling them anyway returns an \
         `isError` result explaining why.\n",
    );
    for group in Group::ALL {
        let _ = write!(out, "\n## {}\n", group.heading());
        for tool in TOOLS.iter().filter(|t| t.group == group) {
            tool_section(&mut out, tool);
        }
    }
    out
}

fn hints(tool: &ToolDef) -> String {
    let h = tool.hints;
    let mut parts = Vec::new();
    if h.read_only {
        parts.push("read-only");
    } else if h.destructive {
        parts.push("**destructive**");
    } else {
        parts.push("writes");
    }
    if h.idempotent {
        parts.push("idempotent");
    }
    if tool.needs_switching {
        parts.push("pinned: hidden");
    }
    parts.join(", ")
}

fn tool_section(out: &mut String, tool: &ToolDef) {
    let _ = write!(out, "\n### {}\n\n", tool.name);
    let _ = write!(out, "**{}** — {}\n\n", tool.title, tool.description);
    let h = tool.hints;
    let _ = writeln!(
        out,
        "Annotations: `readOnlyHint: {}`{}, `idempotentHint: {}`, `openWorldHint: false`.",
        h.read_only,
        if h.read_only {
            String::new()
        } else {
            format!(", `destructiveHint: {}`", h.destructive)
        },
        h.idempotent
    );
    let schema = (tool.input_schema)();
    let props = schema["properties"]
        .as_object()
        .cloned()
        .unwrap_or_default();
    if props.is_empty() {
        out.push_str("\nNo arguments.\n");
    } else {
        let required: Vec<&str> = schema["required"]
            .as_array()
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        // Required first (in schema order), then the rest alphabetically —
        // independent of serde_json's map ordering features.
        let mut names: Vec<&String> = props.keys().collect();
        names.sort_by_key(|n| {
            (
                required.iter().position(|r| r == n).unwrap_or(usize::MAX),
                n.as_str(),
            )
        });
        out.push_str("\n| Argument | Type | Required | Description |\n|---|---|---|---|\n");
        for name in names {
            let prop = &props[name];
            let _ = writeln!(
                out,
                "| `{name}` | {} | {} | {} |",
                type_of(prop),
                if required.contains(&name.as_str()) {
                    "yes"
                } else {
                    "no"
                },
                describe(prop)
            );
        }
    }
    if tool.name == "inspect" {
        out.push_str("\n| `view` | Arguments | Returns |\n|---|---|---|\n");
        for view in INSPECT_VIEWS {
            let params = if view.params.is_empty() {
                "none".to_string()
            } else {
                view.params
                    .iter()
                    .map(|p| format!("`{p}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            };
            let _ = writeln!(out, "| `{}` | {params} | {} |", view.name, view.description);
        }
    }
}

/// A short type label: `string`, `integer`, `string[]`, `object`, enum values.
fn type_of(prop: &Value) -> String {
    if let Some(values) = prop["enum"].as_array() {
        return values
            .iter()
            .filter_map(Value::as_str)
            .map(|v| format!("`{v}`"))
            .collect::<Vec<_>>()
            .join(" \\| ");
    }
    match prop["type"].as_str() {
        Some("array") => format!("{}[]", prop["items"]["type"].as_str().unwrap_or("any")),
        Some(t) => t.to_string(),
        None => "any".to_string(),
    }
}

/// The description plus the schema's constraints.
fn describe(prop: &Value) -> String {
    let mut text = prop["description"].as_str().unwrap_or("").to_string();
    let mut limits = Vec::new();
    match (prop["minimum"].as_u64(), prop["maximum"].as_u64()) {
        (Some(min), Some(max)) => {
            limits.push(format!("{}–{}", group_digits(min), group_digits(max)))
        }
        (Some(min), None) => limits.push(format!("≥ {}", group_digits(min))),
        (None, Some(max)) => limits.push(format!("≤ {}", group_digits(max))),
        (None, None) => {}
    }
    if let Some(max) = prop["maxLength"].as_u64() {
        limits.push(format!("≤ {} bytes", group_digits(max)));
    }
    if let Some(max) = prop["maxItems"].as_u64() {
        limits.push(format!("≤ {max} items"));
    }
    if let Some(pattern) = prop["pattern"].as_str() {
        limits.push(format!("pattern `{pattern}`"));
    }
    if let Some(sub) = prop["properties"].as_object() {
        let mut fields: Vec<String> = sub.keys().map(|k| format!("`{k}`")).collect();
        fields.sort();
        limits.push(format!("fields {}", fields.join(", ")));
    }
    if !limits.is_empty() {
        if !text.is_empty() {
            text.push(' ');
        }
        let _ = write!(text, "({})", limits.join("; "));
    }
    text.replace('|', "\\|")
}

fn group_digits(n: u64) -> String {
    let s = n.to_string();
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (s.len() - i).is_multiple_of(3) {
            out.push(',');
        }
        out.push(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The committed reference must match the registry. On failure,
    /// regenerate it: `neurolithe tools --markdown > docs/src/mcp/tools.md`
    /// (or run the tests with `NEUROLITHE_BLESS_DOCS=1`).
    #[test]
    fn test_committed_tool_reference_is_current() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(REFERENCE_PATH);
        let generated = markdown();
        if std::env::var_os("NEUROLITHE_BLESS_DOCS").is_some() {
            std::fs::write(&path, &generated).unwrap();
        }
        let committed = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            committed == generated,
            "{REFERENCE_PATH} is stale: regenerate it with \
             `neurolithe tools --markdown > {REFERENCE_PATH}` \
             (or NEUROLITHE_BLESS_DOCS=1 cargo test)"
        );
    }

    #[test]
    fn test_reference_covers_every_tool_and_view() {
        let md = markdown();
        for tool in TOOLS {
            assert!(
                md.contains(&format!("### {}\n", tool.name)),
                "{}",
                tool.name
            );
        }
        for view in INSPECT_VIEWS {
            assert!(
                md.contains(&format!("| `{}` |", view.name)),
                "{}",
                view.name
            );
        }
        assert_eq!(group_digits(524288), "524,288");
        assert_eq!(group_digits(256), "256");
    }
}
